//! The standalone host's parity transcript of its Helm chart module, `Parity/helm-chart.transcript.json` at `8b6ccfc`
//! (generated by `HelmTranscript.cs`), replayed against this port (etalii.adp spec 030, task T080): for every chart of
//! its corpus this repository holds (the fourteen fixtures, the `hello-world` example and the `nginx` example the parity
//! script opens), the elements a session delivers at baseline with their payloads, the computed boxes, the property
//! rows of every node, every relation, the empty id and an unknown one, the refused write, the findings, the moves with
//! the project's history and the registration after them. The standalone host's `prometheus` example and its shipped
//! copies are not held here.
//!
//! What differs, and is masked here: the words of a YAML parse error are YamlDotNet's in the transcript and
//! `saphyr-parser`'s here (finding B9 of `helm-chart-disl-fbl` records them as the parser's own), so a payload's
//! `failureMessage`, a row's `Unreadable` value and a `helm.unreadable-yaml` sentence are compared up to the parser's
//! words; the line is compared. A YamlDotNet duplicate key reads the same here. The moves without a history are not
//! replayed: every desktop view has the project's history.

mod common;

use std::fs;

use adp_diagram::{DiagramElement, DiagramProblem, DiagramProblemLocation};
use adp_diagram_helm_chart::{layout, mapper};
use common::open;

const UNKNOWN: &str = "parity:unknown";

fn transcript() -> serde_json::Value {
    serde_json::from_str(include_str!("helm-chart.transcript.json")).unwrap()
}

/// The corpus chart this repository holds for a transcript entry, by fixture name.
fn local_name(chart: &str) -> Option<String> {
    if let Some(name) = chart.strip_prefix("diagrams/helm-chart/backend/EtAlii.Adp.Diagram.HelmChart.Tests/Fixtures/") {
        return Some(name.to_owned());
    }
    match chart {
        "diagrams/helm-chart/examples/hello-world" => Some("examples/hello-world".into()),
        "diagrams/helm-chart/examples/nginx" => Some("examples/nginx".into()),
        _ => None,
    }
}

fn lines(value: &serde_json::Value) -> Vec<String> {
    value
        .as_array()
        .map(|a| a.iter().map(|l| l.as_str().unwrap().to_owned()).collect())
        .unwrap_or_default()
}

/// A string as `Google.Protobuf`'s `JsonFormatter` writes it.
fn proto_string(text: &str) -> String {
    let mut out = String::from("\"");
    for c in text.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{8}' => out.push_str("\\b"),
            '\u{c}' => out.push_str("\\f"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '<' => out.push_str("\\u003c"),
            '>' => out.push_str("\\u003e"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// One message's fields as `JsonFormatter` writes them: a field at its default left out.
struct Message(Vec<String>);

impl Message {
    fn new() -> Self {
        Message(Vec::new())
    }
    fn string(&mut self, name: &str, value: &str) {
        if !value.is_empty() {
            self.0.push(format!("\"{name}\": {}", proto_string(value)));
        }
    }
    fn enumeration(&mut self, name: &str, value: &str) {
        if !value.ends_with("_UNSPECIFIED") {
            self.0.push(format!("\"{name}\": \"{value}\""));
        }
    }
    fn flag(&mut self, name: &str, value: &str) {
        if value == "true" {
            self.0.push(format!("\"{name}\": true"));
        }
    }
    fn number(&mut self, name: &str, value: &str) {
        if !value.is_empty() && value != "0" {
            self.0.push(format!("\"{name}\": {value}"));
        }
    }
    fn list(&mut self, name: &str, value: &str) {
        if !value.is_empty() {
            let items: Vec<String> = value.split(mapper::LIST_SEPARATOR).map(proto_string).collect();
            self.0.push(format!("\"{name}\": [ {} ]", items.join(", ")));
        }
    }
    fn message(&mut self, name: &str, message: Message) {
        self.0.push(format!("\"{name}\": {}", message.text()));
    }
    fn text(&self) -> String {
        if self.0.is_empty() {
            "{ }".to_owned()
        } else {
            format!("{{ {} }}", self.0.join(", "))
        }
    }
}

/// The element as `TranscriptText.PayloadLine` writes it, its payload rebuilt from its attributes in field order.
fn payload_line(element: &DiagramElement) -> String {
    let a = |name: &str| element.attribute(name).to_owned();
    let mut payload = Message::new();
    payload.string("name", &a("name"));
    payload.enumeration("kind", &a("kind"));
    payload.list("chartRelativePath", &a("chartRelativePath").replace('/', "\n"));
    let sub = |fields: &[(&str, &str)]| {
        let mut message = Message::new();
        for (name, kind) in fields {
            let value = a(name);
            let field = name.split_once('.').unwrap().1;
            match *kind {
                "string" => message.string(field, &value),
                "enum" => message.enumeration(field, &value),
                "bool" => message.flag(field, &value),
                "number" => message.number(field, &value),
                _ => message.list(field, &value),
            }
        }
        message
    };
    match element.element_type.as_str() {
        mapper::CHART_TYPE => payload.message(
            "chart",
            sub(&[
                ("chart.version", "string"),
                ("chart.appVersion", "string"),
                ("chart.apiVersion", "string"),
                ("chart.chartType", "string"),
                ("chart.description", "string"),
                ("chart.deprecated", "bool"),
                ("chart.legacy", "bool"),
            ]),
        ),
        mapper::VALUES_TYPE => payload.message(
            "values",
            sub(&[
                ("values.isDefault", "bool"),
                ("values.hasGlobal", "bool"),
                ("values.keyCount", "number"),
            ]),
        ),
        mapper::TEMPLATE_TYPE | mapper::PARTIAL_TYPE => payload.message(
            "template",
            sub(&[
                ("template.role", "enum"),
                ("template.kinds", "list"),
                ("template.kindsUndetermined", "bool"),
                ("template.defines", "list"),
            ]),
        ),
        mapper::DEPENDENCY_TYPE => payload.message(
            "dependency",
            sub(&[
                ("dependency.chartName", "string"),
                ("dependency.alias", "string"),
                ("dependency.constraint", "string"),
                ("dependency.repository", "string"),
                ("dependency.condition", "string"),
                ("dependency.conditionState", "enum"),
                ("dependency.pinnedVersion", "string"),
                ("dependency.resolved", "bool"),
            ]),
        ),
        mapper::SUBCHART_TYPE | mapper::ARCHIVE_TYPE => payload.message(
            "vendored",
            sub(&[
                ("vendored.sealed", "bool"),
                ("vendored.declared", "bool"),
                ("vendored.chartType", "string"),
                ("vendored.chartVersion", "string"),
                ("vendored.templateCount", "number"),
                ("vendored.deeperCount", "number"),
            ]),
        ),
        mapper::EDGE_TYPE => payload.message(
            "edge",
            sub(&[
                ("edge.sourceId", "string"),
                ("edge.targetId", "string"),
                ("edge.kind", "enum"),
                ("edge.label", "string"),
                ("edge.openEnd", "bool"),
            ]),
        ),
        _ => {}
    }
    payload.number("crdCount", &a("crdCount"));
    payload.number("lockEntryCount", &a("lockEntryCount"));
    payload.flag("unreadable", &a("unreadable"));
    payload.number("width", &a("width"));
    payload.number("height", &a("height"));
    payload.string("failureMessage", &a("failureMessage"));
    payload.number("failureLine", &a("failureLine"));
    format!(
        "{} | {} | {}, {} | HelmElementPayload {}",
        element.id,
        element.element_type,
        element.x,
        element.y,
        payload.text()
    )
}

/// `text` with the parser's words after `marker` replaced, up to `end`: what differs between YamlDotNet and
/// `saphyr-parser`.
fn masked(text: &str, marker: &str, end: &str) -> String {
    let mut out = String::new();
    let mut rest = text;
    while let Some(at) = rest.find(marker) {
        let start = at + marker.len();
        out.push_str(&rest[..start]);
        rest = &rest[start..];
        let stop = rest.find(end).unwrap_or(rest.len());
        out.push_str("<parser's words>");
        rest = &rest[stop..];
    }
    out.push_str(rest);
    out
}

fn mask(line: &str) -> String {
    let line = masked(line, "\"failureMessage\": \"", "\"");
    let line = masked(&line, "is not readable YAML: ", "\"");
    let line = masked(&line, "| Unreadable | \"", " (line ");
    masked(&line, "| Failures | \"", " (line ")
}

fn quoted(text: &str) -> String {
    serde_json::to_string(text).unwrap()
}

fn finding_line(problem: &DiagramProblem) -> String {
    let at = match &problem.location {
        Some(DiagramProblemLocation::File { relative_path, line }) => format!("{relative_path}:{line}"),
        other => format!("{other:?}"),
    };
    let severity = format!("{:?}", problem.severity);
    format!(
        "{} | {} | {} | {}",
        problem.rule_id,
        severity,
        at,
        quoted(&problem.message)
    )
}

fn compare(chart: &str, what: &str, expected: &[String], actual: &[String]) {
    let expected: Vec<String> = expected.iter().map(|l| mask(l)).collect();
    let actual: Vec<String> = actual.iter().map(|l| mask(l)).collect();
    for (index, (want, got)) in expected.iter().zip(&actual).enumerate() {
        assert_eq!(want, got, "{chart}: {what} line {index}");
    }
    assert_eq!(expected.len(), actual.len(), "{chart}: {what}: {actual:#?}");
}

fn replay(chart: &str, name: &str, entry: &serde_json::Value) {
    let mut opened = open(name);
    let elements = opened.delivered();
    compare(
        chart,
        "elements",
        &lines(&entry["elements"]),
        &elements.iter().map(payload_line).collect::<Vec<_>>(),
    );

    if entry.get("boxes").is_some() {
        let diagram = adp_diagram_helm_chart::store::get(opened.workspace.documents(), &opened.registration)
            .unwrap()
            .model
            .diagram
            .clone();
        let boxes: Vec<String> = layout::compute(&diagram)
            .iter()
            .map(|(id, r)| format!("{id} | {}, {}, {} x {}", r.x, r.y, r.width, r.height))
            .collect();
        compare(chart, "boxes", &lines(&entry["boxes"]), &boxes);

        for target in entry["rows"].as_array().unwrap() {
            let id = target["target"].as_str().unwrap();
            let rows: Vec<String> = opened
                .session
                .properties(opened.workspace.documents(), &[id])
                .iter()
                .map(|row| {
                    format!(
                        "{} | {} | {} | Line | read-only ({}) | group {}",
                        row.id,
                        row.label,
                        quoted(&row.value),
                        row.read_only_reason,
                        row.group
                    )
                })
                .collect();
            compare(chart, &format!("rows of '{id}'"), &lines(&target["rows"]), &rows);
        }

        let first = diagram.nodes().first().map(|n| n.id()).unwrap_or_default();
        let write = opened
            .session
            .set_property(&mut opened.workspace, &[first.as_str()], "helm.name", "Renamed")
            .err()
            .map_or("ok".to_owned(), |e| format!("refused: {e}"));
        assert_eq!(entry["write"].as_str().unwrap(), write, "{chart}: write");

        let findings: Vec<String> = opened
            .session
            .problems(opened.workspace.documents())
            .iter()
            .map(finding_line)
            .collect();
        compare(chart, "findings", &lines(&entry["findings"]), &findings);
    }

    // The moves with a history: a reparent, a node, a relation and an unknown id, each to (10.5, -20.25).
    let diagram = adp_diagram_helm_chart::store::get(opened.workspace.documents(), &opened.registration)
        .unwrap()
        .model
        .diagram
        .clone();
    let node = diagram.nodes().first().map(|n| n.id());
    let relation = mapper::relations(&diagram).first().map(|r| r.id());
    let answer = |result: Result<(), String>| match result {
        Ok(()) => "accepted".to_owned(),
        Err(e) => format!("refused: {e}"),
    };
    let label = "with a history";
    let reparented = node.clone().unwrap_or_else(|| UNKNOWN.to_owned());
    let mut moves = vec![format!(
        "{label}: reparent {reparented} under {UNKNOWN} => {}",
        answer(
            opened
                .session
                .move_element(&mut opened.workspace, &reparented, Some(UNKNOWN), 0)
        )
    )];
    for (what, id) in [
        ("node", node),
        ("relation", relation),
        ("unknown id", Some(UNKNOWN.to_owned())),
    ] {
        moves.push(match id {
            None => format!("{label}: move a {what} => there is none"),
            Some(id) => format!(
                "{label}: move {what} {id} to (10.5, -20.25) => {}",
                answer(opened.session.move_element_to(&mut opened.workspace, &id, 10.5, -20.25))
            ),
        });
    }
    let expected: Vec<String> = lines(&entry["moves"])
        .into_iter()
        .filter(|l| l.starts_with(label))
        .collect();
    compare(chart, "moves", &expected, &moves);

    let text = fs::read_to_string(&opened.registration).unwrap();
    let mut after: Vec<String> = text.split('\n').map(|l| l.trim_end_matches('\r').to_owned()).collect();
    if text.ends_with('\n') {
        after.pop();
    }
    compare(
        chart,
        "registration after the moves",
        &lines(&entry["registrationAfterMoves"]),
        &after,
    );
}

#[test]
fn every_chart_of_the_standalone_transcript_reads_as_it_did() {
    let transcript = transcript();
    let mut replayed = 0;
    for entry in transcript["charts"].as_array().unwrap() {
        let chart = entry["chart"].as_str().unwrap();
        let Some(name) = local_name(chart) else {
            continue;
        };
        replay(chart, &name, entry);
        replayed += 1;
    }
    assert_eq!(replayed, 16);
}
